    try _v.visit(field: VT.NAME, fieldName: "NAME", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.ABBREVIATION, fieldName: "ABBREVIATION", required: false, type: ForwardOffset<String>.self)
