    try _v.visit(field: VT.CROSS_IDS, fieldName: "CROSS_IDS", required: false, type: ForwardOffset<Vector<ForwardOffset<SSYCrossIdentifier>, SSYCrossIdentifier>>.self)
    try _v.visit(field: VT.SYSTEM_CLASS, fieldName: "SYSTEM_CLASS", required: false, type: ssySystemKind.self)
    try _v.visit(field: VT.MORPHOLOGY, fieldName: "MORPHOLOGY", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.HOST_ID, fieldName: "HOST_ID", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.CONFIRMED_REAL, fieldName: "CONFIRMED_REAL", required: false, type: ssyVerdict.self)
    try _v.visit(field: VT.CONFIRMED_GALAXY, fieldName: "CONFIRMED_GALAXY", required: false, type: ssyVerdict.self)
    try _v.visit(field: VT.CONFIRMED_STAR_CLUSTER, fieldName: "CONFIRMED_STAR_CLUSTER", required: false, type: ssyVerdict.self)
    try _v.visit(field: VT.FALSE_POSITIVE, fieldName: "FALSE_POSITIVE", required: false, type: ssyFalsePositiveVerdict.self)
    try _v.visit(field: VT.FALSE_POSITIVE_REFS, fieldName: "FALSE_POSITIVE_REFS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.DISCOVERY_YEAR, fieldName: "DISCOVERY_YEAR", required: false, type: Int32.self)
    try _v.visit(field: VT.DISCOVERY_REFS, fieldName: "DISCOVERY_REFS", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
    try _v.visit(field: VT.NOTES, fieldName: "NOTES", required: false, type: ForwardOffset<Vector<ForwardOffset<String>, String>>.self)
