    try _v.visit(field: VT.DISTANCE_METHOD_TEXT, fieldName: "DISTANCE_METHOD_TEXT", required: false, type: ForwardOffset<String>.self)
    try _v.visit(field: VT.PARALLAX, fieldName: "PARALLAX", required: false, type: ForwardOffset<EXOParameter>.self)
